        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 18299.0, "series": [{"data": [[0.0, 18240.0], [200.0, 1.0], [1000.0, 5.0]], "isOverall": false, "label": "SeleccionTarifaYCantidad", "isController": false}, {"data": [[0.0, 18164.0], [200.0, 1.0], [1000.0, 9.0]], "isOverall": false, "label": "Pago", "isController": false}, {"data": [[0.0, 18299.0], [1000.0, 9.0]], "isOverall": false, "label": "Tarifas", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 1000.0, "title": "Response Time Distribution"}},
